/** Une conversation pilotée à la main : chaque message rendu est gardé pour le contrôle de forme. */
function pilote(A, tous) {
  const garde = r => { for (const m of (Array.isArray(r) ? r : (r && r.envoyer) || [])) tous.push(m); return r; };
  return { garde, b: (k, v) => garde(A.surBouton(`acc:${A.conversation()?.id || '000000'}:${k}:${v}`)), t: x => garde(A.surTexte(x)) };
}
