    '    e = ["-f", "lavfi", "-i", "color=c=0x8a8a8a:s=%dx%d:d=%s:r=10" % (w, h, duree), "-f", "lavfi", "-i", "color=c=%s:s=%dx%d:d=%s:r=10" % (couleur, cw, ch, duree), "-f", "lavfi", "-i", "color=c=0x303030:s=%dx%d:d=%s:r=10" % (tw, th, duree)]',
    '    ch_ = "[0][1]overlay=x=\'W*0.34+W*0.15*sin(t+%s)\':y=H*0.40[a];[a][2]overlay=x=W*0.42:y=H*0.12[b]" % phase',
    '    r = subprocess.run(["ffmpeg", "-v", "error"] + e + ["-filter_complex", ch_, "-map", "[b]", "-t", str(duree), "-pix_fmt", "yuv420p", dest, "-y"], capture_output=True, text=True)',
    '    return r.returncode == 0',
    'ok = True',
    'A = os.path.join(B, "A"); os.makedirs(A)',
