    'for i in range(2): ok = video(os.path.join(A, "rouge-proche-%d.mp4" % i), "0xc06020", phase=i + 0.5) and ok',
    'for i in range(3): ok = video(os.path.join(A, "bleu-%d.mp4" % i), "0x2040c0", phase=i) and ok',
