  if (c3.rap.couleurs_trouvees !== 3 || !sc || sc.captures.length || sc.sans_capture !== true || !sc.apercu || !fs.existsSync(sc.apercu) || JSON.stringify(c3.rap.familles_sans_capture) !== JSON.stringify([c3.rap.familles.indexOf(sc) + 1]) || c3.rap.invariant.sans_photo !== 1 || !invOk(c3.rap)) throw new Error(`(3) sans capture : ${c3.rap.couleurs_trouvees} famille(s), ${JSON.stringify(sc)}, ${JSON.stringify(c3.rap.invariant)}`);
  // (4) la mission : le nombre DIT passé à captures.py, l'invariant dans l'historique et la mission, l'écart nommé (4 dites, 3 trouvées)
  const lances = [];
  const Ms = missionsM.ouvrirMissions({ maison: path.join(base, 'maison'), atelier, travaux: { lancer: async spec => { lances.push(spec); return T.lancer(spec); } }, claude: async () => { throw new Error('pas de Claude ici'); }, telegram: () => null, depot: {}, reglages: () => ({ ffmpegDossier: ffDossier }), pauseReessaiMs: 10 });
  const m = Ms.creer({ id: 'c0mpte-1', lien: lienEssai, reponses: { nom: 'Robe Compte', niche: 'hijab', couleurs: 4 } }, null, { demarrer: false });
  m.d.rushes = path.join(base, 'C');
  let err = ''; try { await Ms._etapes.captures(m); } catch (e) { err = e.message; }
  const premiere = lances.find(s => s.nom.endsWith('/captures'));
