  const msg = vus[0].message;
  if (!/DARIJA ALGÉRIENNE/.test(msg) || !msg.includes(JSON.stringify(script)) || vus[0].outils.length || vus[0].dept !== 'page' || !/EXACTEMENT cinq angles/.test(msg) || !/6900 دج/.test(msg)) throw new Error('message de l\'étape textes : ' + msg.slice(0, 300));
