    if (!pres(o.pmin, b.prixPlancher) || !pres(o.lmin, b.livraisonPlancher)) throw new Error(`cas ${i + 1} : planchers ${o.pmin} / ${o.lmin} contre ${b.prixPlancher} / ${b.livraisonPlancher}`);
