  if (A.surTexte('الغي')[0].texte !== accueil.TEXTES.annule.join('\n')) throw new Error('الغي');
  garde(A.commencer(lienEssai)); const id = A.conversation().id; A.surBouton(`acc:${id}:n:1`); A.surTexte('2300');
  const r = garde(A.surBouton(`acc:${vieux}:stock:test`)), FAT = accueil.TEXTES.zarFat.join('\n');
  if (!Array.isArray(r) || r.length !== 2 || r[0].texte !== FAT || !/سعر البيع/.test(r[1].texte) || !JSON.stringify(r[1].boutons).includes(`acc:${id}:annule:1`) || r.some(x => /ابعث لينك جديد/.test(x.texte))) throw new Error('vieux bouton, conversation ouverte : ' + JSON.stringify(r));
  if (A.conversation().id !== id || A.conversation().reponses.stock !== undefined) throw new Error('le vieux bouton a répondu à la conversation en cours');
