  for (const [k, v] of [['stock', 'test'], ['compte', '0'], ['page', '0'], ['mode', 'site'], ['placements', 'story_reels'], ['creas', '4'], ['niche', 'hijab']]) B.surBouton(`acc:${idL}:${k}:${v}`);
  const ra = garde(B.surBouton('acc:aaaaaa:stock:test'));
