  const Q0 = /شحال من موديل/, ANN = accueil.TEXTES.annule.join('\n'), ENCH = accueil.TEXTES.annuleEtLien.join('\n'), FAT = accueil.TEXTES.zarFat.join('\n');
  const bouton = (m, id) => (m.boutons || []).flat().find(x => x.texte === 'الغي' && x.data === `acc:${id}:annule:lien`);
