  let r = garde(A.surTexte('هاذا لينك آخر ' + neuf));
  if (r.length !== 1 || r[0].texte !== ENC || !bouton(r[0], id1) || A.conversation().lienEnAttente !== neuf || A.conversation().reponses.gros !== 2300) throw new Error('lien neuf pendant la fiche : ' + JSON.stringify({ r, conv: A.conversation() }));
