  r = garde(A.surBouton(`acc:${id2}:annule:lien`)); if (r.length !== 1 || r[0].texte !== accueil.TEXTES.questionFatet.join('\n') || A.conversation()) throw new Error('2e clic, plus de fiche : ' + JSON.stringify(r));
