  r = garde(A.surTexte('الغي')); if (r.length !== 2 || r[0].texte !== ENCH || !Q0.test(r[1].texte) || A.conversation()?.lien !== neuf) throw new Error('« الغي » tapé avec un lien en attente : ' + JSON.stringify(r));
