  const { garde } = pilote(A, tous);
  const neuf = 'https://drive.google.com/drive/folders/1NeufNeufNeufNeuf22', Q0 = /شحال من موديل/, ANN = accueil.TEXTES.annule.join('\n');
  const SUIV = (accueil.TEXTES.lienQuiAttendait || ['(absent)']).join('\n');
  const fautes = [];
  // 1. le même dossier, écrit autrement
  for (const autre of [lienEssai + '?usp=sharing', lienEssai.replace('/drive/folders/', '/drive/u/0/folders/'), lienEssai + '/']) {
    garde(A.commencer(lienEssai)); const id = A.conversation().id; garde(A.surTexte(autre));
    if (A.conversation().lienEnAttente) fautes.push(`« ${autre} » (le même dossier) pris pour un lien neuf`);
    const r = garde(A.surBouton(`acc:${id}:annule:lien`)); if (!Array.isArray(r) || r.length !== 1 || r[0].texte !== ANN || A.conversation()) fautes.push(`« الغي » après « ${autre} » : ` + JSON.stringify(r).slice(0, 160));
    A.annuler();
  }
  garde(A.commencer(lienEssai)); garde(A.surTexte(neuf)); garde(A.surTexte(lienEssai + '?usp=drive_link'));
  if (A.conversation().lienEnAttente) fautes.push('le dossier de la fiche renvoyé après un lien neuf : le lien neuf attend encore');
  A.annuler();
