/** Un client MCP (stdio) du serveur local, lancé EXACTEMENT comme le fichier --mcp-config d'un tour le déclare. */
function clientMcp(plus = {}) {
  exigeMM();
  const conf = mm.configMcp({ config: cfgMeta, portes: portesMeta, journal: journalMeta, graph: baseFG, ...plus }).mcpServers[mm.NOM_SERVEUR];
  const p = spawn(conf.command, conf.args, { stdio: ['pipe', 'pipe', 'pipe'], env: { PATH: process.env.PATH } });
  let tampon = '', n = 0; const attente = new Map(); let err = '';
  p.stderr.on('data', d => err += d);
  p.stdout.on('data', d => { tampon += d; let i; while ((i = tampon.indexOf('\n')) >= 0) { const l = tampon.slice(0, i); tampon = tampon.slice(i + 1); if (!l.trim()) continue; const m = JSON.parse(l); const f = attente.get(m.id); if (f) { attente.delete(m.id); f(m); } } });
  const appel = (method, params) => new Promise((ok, ko) => { const id = ++n; const t = setTimeout(() => ko(new Error(`${method} : pas de réponse (${err.slice(0, 200)})`)), 15000); attente.set(id, m => { clearTimeout(t); ok(m); }); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n'); });
  const outil = async (name, args = {}) => { const m = await appel('tools/call', { name, arguments: args }); const texte = m.result.content[0].text; let obj = null; try { obj = JSON.parse(texte); } catch {} return { isError: !!m.result.isError, texte, obj }; };
  return { appel, outil, conf, fermer: () => { try { p.stdin.end(); } catch {} setTimeout(() => { try { p.kill('SIGKILL'); } catch {} }, 500); } };
}
const OUTILS_META_ATTENDUS = ['ads_get_ad_accounts', 'ads_get_ad_account_pages', 'ads_get_ad_entities', 'ads_get_field_context', 'ads_creative_upload_media', 'ads_get_ad_videos', 'ads_get_ad_images', 'ads_get_ig_accounts', 'ads_get_datasets', 'ads_get_creatives', 'ads_create_campaign', 'ads_create_ad_set', 'ads_create_creative', 'ads_create_ad', 'ads_activate_entity', 'ads_update_entity'];

