    const futur = new Date(Date.now() + 3 * 3600000), iso = futur.toISOString().replace(/\.\d{3}Z$/, 'Z');
    const porte = mm.ecrirePorte(portesMeta, { mission: 'lot:L1', ids: ['C7', 'S7a', 'S7b', 'A7a'], adSets: ['S7a', 'S7b'] });
    const autre = mm.ecrirePorte(portesMeta, { mission: 'lot:L2', ids: ['C8', 'S8a'], adSets: ['S8a'] });
    const essai = (o, f) => c.outil('ads_update_entity', { ad_account_id: '111', entity_id: 'S7a', entity_type: 'adset', fields: JSON.stringify(f || { start_time: iso }), porte, ...o });
    const refus = [];
    for (const [quoi, o, f, re] of [['sans porte', { porte: undefined }, null, /aucune porte/], ['porte d\'un autre lot', { porte: autre }, null, /pas un ad set de la porte/], ['campagne', { entity_id: 'C7', entity_type: 'campaign' }, null, /un ad set seulement/],
      ['annonce de la porte', { entity_id: 'A7a', entity_type: 'adset' }, null, /pas un ad set de la porte/], ['avec un budget', {}, { start_time: iso, daily_budget: 900 }, /SEUL/], ['avec un status', {}, { start_time: iso, status: 'PAUSED' }, /SEUL/],
      ['passé', {}, { start_time: new Date(Date.now() - 3600000).toISOString() }, /futur/], ['huit jours', {}, { start_time: new Date(Date.now() + 8 * 86400000).toISOString() }, /sept jours/], ['sans fuseau', {}, { start_time: iso.replace('Z', '') }, /fuseau/],
      ['status ACTIVE caché', {}, { start_time: iso, status: 'ACTIVE' }, /SEUL/]]) {
      const r = await essai(o, f);
      if (!r.isError || !re.test(r.obj?.error?.message || '')) throw new Error(`${quoi} : ${r.texte}`);
      refus.push(quoi);
    }
    if (posts().length !== p0) throw new Error('une écriture est partie chez Meta malgré un refus');
    const ok = await essai({}, null);
    const pst = posts().slice(p0);
    if (ok.isError || pst.length !== 1 || pst[0].p !== `/${mm.VERSION_GRAPH}/S7a` || JSON.stringify(Object.keys(pst[0].corps)) !== '["start_time"]' || Date.parse(pst[0].corps.start_time.replace(/\+0000$/, 'Z')) !== Date.parse(iso)) throw new Error('accepté : ' + ok.texte + ' ' + JSON.stringify(pst.map(x => [x.p, x.corps])));
    if (!ok.obj.relu || ok.obj.relu.start_time !== pst[0].corps.start_time || ok.obj.relu.effective_status !== 'SCHEDULED' || !FG.vus.some(v => v.m === 'GET' && v.p === `/${mm.VERSION_GRAPH}/S7a`)) throw new Error('pas relu : ' + ok.texte);
    // la porte n'est pas consommée : l'activation de cet ad set passe ensuite, une fois
    const act = await c.outil('ads_activate_entity', { ad_account_id: '111', entity_id: 'S7a', entity_type: 'adset', porte });
    const act2 = await c.outil('ads_activate_entity', { ad_account_id: '111', entity_id: 'S7a', entity_type: 'adset', porte });
    if (act.isError || !act2.isError) throw new Error('activation après l\'heure : ' + act.texte + ' | ' + act2.texte);
    // un ad set déjà activé : son heure ne se repose plus
    const apres = await essai({}, null); if (!apres.isError || !/déjà activé/.test(apres.obj.error.message)) throw new Error('heure reposée sur un ad set déjà activé : ' + apres.texte);
    // un tour de PAUSE : refusé
