    const cp = clientMcp({ pause: tk });
    try { const rp = await cp.outil('ads_update_entity', { ad_account_id: '111', entity_id: 'S7b', entity_type: 'adset', fields: JSON.stringify({ start_time: iso }), porte }); if (!rp.isError || !/tour de PAUSE/.test(rp.obj.error.message)) throw new Error('tour de pause : ' + rp.texte); } finally { cp.fermer(); }
    await dormir(100);
