    w.rep.activation = a => { vu = { chemin: a.cheminMeta, porte: /porte "/.test(a.message) }; return tourAr([brutAr('PUBLISHING')])(); };
    await w.Ms.avancer(w.m());
    if (!vu || vu.chemin !== 'connecteur' || vu.porte || FG.vus.length !== n0 || !w.m().historique.some(h => /avant le serveur local/.test(h.quoi))) throw new Error(JSON.stringify({ vu, lectures: FG.vus.length - n0 }));
