    for (const [nom, r] of [['200 HTML', html], ['autre compte', autre], ['compte sans statut', sansStatut], ['page vide', pageVide], ['sans page', sansPage], ['sans compte', sansCompte]]) { if (r.ok !== false) throw new Error(`sonde « ${nom} » verte : ${JSON.stringify(r).slice(0, 200)}`); out.push(`${nom} → ${r.refus}`); }
