    fs.writeFileSync(path.join(sortie, '_rapport.json'), JSON.stringify({ familles, manque: [], ecart_nombre_dit: { vu_par_l_outil: null }, deuxieme_passe: c !== 'auto' && k < +c ? { tentee: true, retenue: false, familles_avant: k, familles_apres: k } : { tentee: false } }));
