    const m = Ms.creer({ lien: lienEssai, reponses: { nom: 'Abaya Lina', niche: 'hijab' } }, { id, rang: 1, total: 2, nom: 'Abaya Lina', couleurs: [], rushes: vide, couleursClient: false }, { demarrer: false });
