    if (P.length !== 1 || p.length !== 1 || p[0].etat !== 'ouverte' || p[0].modeles.map(mo => mo.id).join() !== ids.join() || !['Robe Sara', 'Kaftan Nour', 'Abaya Lina'].every(n => P[0].t.includes(`\n${n} · `))) throw new Error('la porte du tick : ' + JSON.stringify({ questions: P.length, portes: p.map(x => [x.gen, x.etat, x.modeles.map(mo => mo.id)]) }));
