  if (r.fermees !== 2 || pA.etat !== 'refusee' || !pA.annuleeLe || !stS.annulee || pB.etat !== 'validee' || w.tours.length !== t0) throw new Error('après « الغي » : ' + JSON.stringify({ fermees: r.fermees, A: pA.etat, S: stS, B: pB.etat, tours: w.tours.length - t0 }));
