  const vieuxA = w.portes()[0].b[0][0].data;
  for (const id of ['c2b001', 'c2b002']) await w.Ms.avancer(w.m(id));
  await w.attendre(() => w.portes().length >= 2); await dormir(80);
  const pA = () => w.L('c1a0c1').portes.liste, pB = () => w.L('c2b0c2').portes.liste;
  const qB = w.portes()[w.portes().length - 1];
  const b1 = pB()[0];
  if (w.ouvertes() !== 1 || pA()[0].etat !== 'reprise' || JSON.stringify(pA()[0].reprisePar) !== JSON.stringify({ lot: 'c2b0c2', gen: 1 }) || b1.modeles.map(mo => mo.id).join() !== 'c2b001,c2b002,c1a001,c1a002') throw new Error('la porte neuve ne reprend pas : ' + JSON.stringify({ ouvertes: w.ouvertes(), A: pA().map(p => [p.gen, p.etat, p.reprisePar]), B: pB().map(p => [p.gen, p.etat, p.modeles.map(mo => mo.id)]) }));
  formeOk(qB.t);
  if (!/سكّرت الأسئلة تاع لانسي لي قبل/.test(qB.t) || !['Abaya Lina', 'Hijab Maya', 'Robe Sara', 'Kaftan Nour'].every(n => qB.t.includes(`\n${n} · `))) throw new Error('la porte neuve ne nomme pas les quatre modèles ni la reprise :\n' + qB.t);
  const h = b1.modeles.map(mo => Date.parse(mo.heure)); if (h.some((x, i) => i && x - h[i - 1] !== 2 * 3600000)) throw new Error('heures : ' + JSON.stringify(b1.modeles.map(mo => mo.heure)));
  // LA GARDE (le ping-pong vu chez le vendeur le 14/10 à 02:00) : le lot repris ne repose rien, ni par événement ni par l'horloge
  const nP = w.portes().length;
  await w.Ms._verifierPorteLot(w.m('c1a001')); await w.Ms._verifierPorteLot(w.m('c1a002'));
  for (let i = 0; i < 3; i++) { w.Ms.tick(w.tot()); await dormir(120); }
  if (w.portes().length !== nP || pA().length !== 1 || pB().length !== 1 || w.ouvertes() !== 1 || pB()[0].etat !== 'ouverte') throw new Error('PING-PONG : ' + JSON.stringify({ questions: w.portes().length - nP, A: pA().map(p => [p.gen, p.etat]), B: pB().map(p => [p.gen, p.etat]) }));
  if ((await w.Ms.surBouton(vieuxA)).texte !== 'هاذ السؤال فات' || w.tours.length) throw new Error('le vieux « لانسي » du lot repris lance encore');
  // une mission SEULE prête pendant la porte : pas de 2e question, la porte est refaite avec elle
  await w.Ms.avancer(w.m('c3e001')); await dormir(120);
  const b2 = pB()[pB().length - 1];
  if (w.seules().length || w.ouvertes() !== 1 || pB().length !== 2 || pB()[0].etat !== 'reprise' || b2.etat !== 'ouverte' || b2.modeles.map(mo => mo.id).sort().join() !== 'c1a001,c1a002,c2b001,c2b002,c3e001' || JSON.stringify(pA()[0].reprisePar) !== JSON.stringify({ lot: 'c2b0c2', gen: 2 })) throw new Error('mission seule pendant la porte : ' + JSON.stringify({ seules: w.seules().length, ouvertes: w.ouvertes(), B: pB().map(p => [p.gen, p.etat, p.modeles.map(mo => mo.id)]), A: pA()[0].reprisePar }));
  const q2 = w.portes()[w.portes().length - 1]; formeOk(q2.t);
  if ((await w.Ms.surBouton(qB.b[0][0].data)).texte !== 'هاذ السؤال فات') throw new Error('le « لانسي » de la porte refaite lance encore');
  // « لانسي » sur la seule porte : les cinq, une par une, une fois chacun
  if ((await w.Ms.surBouton(q2.b[0][0].data)).texte !== 'وصلني') throw new Error('« لانسي » refusé');
  const ids = ['c1a001', 'c1a002', 'c2b001', 'c2b002', 'c3e001'];
  await w.attendre(() => ids.every(id => w.m(id).etat === 'suivi'));
  const acts = w.tours.filter(t => t.e === 'activation');
  if (acts.length !== 5 || w.maxEnVol !== 1 || ids.some(id => w.m(id).historique.filter(x => /activation : /.test(x.quoi) && /posée|relu|ACTIVE|programm/i.test(x.quoi)).length < 1)) throw new Error(`activations : ${acts.length} tour(s), ${w.maxEnVol} en même temps`);
  for (let i = 0; i < 2; i++) { w.Ms.tick(w.tot()); await dormir(120); }
  if (w.ouvertes() !== 0 || w.portes().length !== nP + 1 || w.tours.filter(t => t.e === 'activation').length !== 5) throw new Error('après les activations, l\'horloge a rouvert : ' + JSON.stringify({ ouvertes: w.ouvertes(), q: w.portes().length - nP - 1 }));
  return `porte de B reprend A (4 modèles, dit) · garde : 2 événements + 3 ticks → 0 · mission seule → porte refaite (5) · « لانسي » → 5 activations une par une`;
