  const c = (nom, k, rang) => ({ nom, rang, exclue: false, captures: Array.from({ length: k }, (_, i) => `${nom}-${i}.jpg`) });
  const fiche = [c('Bleu', 4, 4), c('Noir', 2, 1), c('Rouge', 2, 3), c('Beige', 2, 2)];
  if (missionsM.ordreDesCouleurs(fiche, 'nommees').join() !== 'Noir,Beige,Rouge,Bleu') throw new Error('ordre nommé : ' + missionsM.ordreDesCouleurs(fiche, 'nommees').join());
  const rot = missionsM.photosAlternees(fiche, 15, 'nommees').map(x => x.couleur), vieux = missionsM.photosAlternees(fiche, 15, 'fournie').map(x => x.couleur);
  if (rot.slice(0, 5).join() !== 'Noir,Beige,Rouge,Bleu,Noir' || rot.some((x, k) => k && x === rot[k - 1]) || rot.length !== 10) throw new Error('rotation : ' + rot.join(','));
  if (vieux[0] !== 'Bleu') throw new Error('l\'ancien comportement (la plus fournie d\'abord) a disparu : ' + vieux.join(','));
  // une couleur épuisée : la rotation continue sur les restantes, jamais deux fois la même
  const ep = missionsM.photosAlternees([c('Noir', 3, 1), c('Beige', 1, 2), c('Rouge', 3, 3)], 15, 'nommees').map(x => x.couleur[0]).join('');
  if (!/^NBR/.test(ep) || /(.)\1/.test(ep) || ep.length !== 7) throw new Error('couleur épuisée : ' + ep);
  let graine = 11; const hasard = n => { graine = (graine * 1103515245 + 12345) % 2147483648; return graine % n; };
  for (let i = 0; i < 400; i++) {
    const noms = ['Noir', 'Beige', 'Rouge', 'Bleu'].slice(0, 2 + hasard(3)), cs = noms.map((n, r) => c(n, hasard(9), r + 1));
    const o = missionsM.photosAlternees(cs, 15, 'nommees'), v = missionsM.photosAlternees(cs, 15, 'fournie');
    if (o.some((x, k) => k && x.couleur === o[k - 1].couleur) || o.length !== v.length) throw new Error(`tirage ${i} : ${o.map(x => x.couleur[0]).join('')} / ancien ${v.map(x => x.couleur[0]).join('')}`);
  }
  // le bureau passe l'ordre nommé à l'outil
  const maisonO = fs.mkdtempSync(path.join(os.tmpdir(), 'manita-ordre-')); let args = null;
  const MsO = missionsM.ouvrirMissions({ maison: maisonO, atelier: path.join(maisonO, 'pas-d-atelier'), depot: {}, reglages: () => ({ codeBoutique: 'SHOP' }), claude: async () => { throw new Error('pas de Claude'); }, telegram: () => null,
    travaux: { lancer: async spec => { args = spec.args; return { code: 1, sortie: 'arret', json: [] }; } } });
  const mO = { id: 'aj0001', code: 'ORDR', etat: 'encours', historique: [], etapes: {}, demande: { reponses: { detail: 6900, tailles: 'standard', sku: 'par-taille' } },
    d: { textes: { nom: 'Abaya Ordre', blocs: ['a', 'b', 'c'] }, couleurs: fiche, photosPage: ['Bleu', 'Noir', 'Bleu', 'Beige', 'Rouge', 'Bleu'].map((n, i) => ({ couleur: n, cdn: `https://c/${i}` })) } };
  try { await MsO._etapes.paquet(mO); } catch {}
  if (!args || args[args.indexOf('--ordre-couleurs') + 1] !== 'Noir,Beige,Rouge,Bleu') throw new Error('--ordre-couleurs passé à l\'outil : ' + (args ? args[args.indexOf('--ordre-couleurs') + 1] : 'aucun'));
  // l'outil le respecte (et son contrôle d'alternance l'accepte) ; sans ordre, l'ancien
  const py = travauxM.trouverPython(''), prod = path.resolve(RACINE, '..', 'outils', '2-PAGE-PRODUIT-SKU', 'manita-produit.py');
  const code = `import importlib.util, json, sys, inspect
sys.dont_write_bytecode = True
s = importlib.util.spec_from_file_location('p', sys.argv[1]); p = importlib.util.module_from_spec(s); s.loader.exec_module(p)
ph = [{"couleur": c, "url": "u%s%d" % (c, i)} for c, k in (("Bleu", 4), ("Noir", 2), ("Rouge", 2), ("Beige", 2)) for i in range(k)]
if "ordre" not in inspect.signature(p.alterne_couleurs).parameters:
    print(json.dumps({"absent": True})); sys.exit(0)
o, r = p.alterne_couleurs([dict(x) for x in ph], ["Noir", "Beige", "Rouge", "Bleu"])
v, rv = p.alterne_couleurs([dict(x) for x in ph])
print(json.dumps({"o": [x["couleur"] for x in o], "r": len(r), "f": p.controle_alternance(o + r), "v": [x["couleur"] for x in v]}))`;
  const x = spawnSync(py, ['-c', code, prod], { encoding: 'utf8', env: { ...process.env, PYTHONDONTWRITEBYTECODE: '1' } });
  let j; try { j = JSON.parse(x.stdout.trim().split('\n').pop()); } catch { throw new Error('manita-produit illisible : ' + (x.stderr || x.stdout).slice(-300)); }
