  // 1. réécrite APRÈS la relecture juste : avec le nom dans la même charge, ou seule mais abîmée — le stocké n'est plus celui relu
  for (const [quoi, apres] of [['réécrite avec le nom après la relecture', up({ productId: 'P9', name: 'Abaya Seule', description: abime })], ['réécrite seule, abîmée, après la relecture', up({ productId: 'P9', description: abime })]]) {
    const r = ev([up({ productId: 'P9', description: desc }), get({ id: 'P9', description: desc }), apres]);
    if (r.ok) fautes.push(`${quoi} : ACCEPTÉE`);
  }
  // 2. la VARIANTE lue à la place du produit (le produit sans « id », la variante porte productId = le parent)
  { const r = ev([up({ productId: 'P9', description: desc }), get({ data: { _id: 'P9', name: 'Abaya Seule', description: abime, variants: [{ sku: 'ABA-NOI-M', productId: 'P9', description: desc }] } })]);
    if (r.ok) fautes.push('variante (productId du parent) lue à la place du produit abîmé : ACCEPTÉE'); }
  { const r = ev([up({ productId: 'P9', description: desc }), get({ data: { name: 'Abaya Seule', description: abime, variants: [{ variantId: 'V1', productId: 'P9', description: desc }] } })]);
    if (r.ok) fautes.push('variante (variantId, productId du parent) lue à la place du produit sans id : ACCEPTÉE'); }
