  const Ms = missionsM.ouvrirMissions({ maison: maisonP, atelier: path.join(maisonP, 'x'), travaux: { lancer: async () => ({ code: 1, sortie: '', json: [] }) }, depot: {}, pauseReessaiMs: 0, reglages: () => ({}),
    claude: async a => rendre(a), telegram: () => ({ envoyer: async (t, o = {}) => { envoyes.push(typeof t === 'string' ? t : t.texte); return { envoye: true }; } }) });
  const mk = id => ({ id, code: 'PUB', etat: 'encours', historique: [], etapes: { 'page-ok': {} }, demande: { reponses: { mode: 'site' } }, d: { paquet: paquetF, produit: { productId: 'P9', storeId: 'S1', urlProduit: '' } } });
