  { const w = mondePorte({ tombe: false }), pend = new Promise(() => {});
    w.rep = () => pend; // le PC se coupe pendant le premier tour
    for (const id of [s, k, a]) await w.Ms.avancer(w.m(id));
    await w.Ms.surBouton(w.portes()[0].b[0][0].data);
    await w.attendre(() => w.tours.length === 1); await dormir(150); // le faux tour a pris sa réponse (suspendue) : le PC se coupe
    await w.Ms.arreter(k, 'le client a pressé « حبس »');
    const nAvant = w.tours.length; w.enVol = 0; w.maxEnVol = 0; w.tickets = [];
    w.rep = x => w.activation(x);
    w.ouvrir(); w.Ms.redemarrer();
    await w.attendre(() => w.m(a).etat === 'suivi');
    await dormir(200);
    const apres = w.tours.slice(nAvant).filter(x => x.e === 'activation'), deS = apres.filter(x => x.a.message.includes('la campagne C1,'));
    if (deS.length) fautes.push(`coupure pendant l'activation de Robe Sara : ${deS.length} 2e activation(s) au redémarrage`);
    if (apres.length !== 1) fautes.push(`coupure : ${apres.length} tour(s) d'activation au redémarrage au lieu d'un (Abaya Lina)`);
    const t = w.tickets[0]?.contenu;
    if (!t || JSON.stringify([...t.ids].sort()) !== JSON.stringify(objetsDe(3).sort())) fautes.push('porte réécrite après la coupure : ' + JSON.stringify(t ? t.ids : null) + ' au lieu des seuls objets d\'Abaya Lina' + (t && t.ids.some(id => /2/.test(id)) ? ' (le modèle ARRÊTÉ y est)' : ''));
    if (w.m(s).etat !== 'encours' || w.m(s).attente !== 'activation' || !w.m(s).d.publication) fautes.push('Robe Sara n\'est pas en relecture : ' + JSON.stringify({ etat: w.m(s).etat, attente: w.m(s).attente }));
    if (w.m(k).etat !== 'arretee' || w.tours.some(x => x.e === 'activation' && x.a.message.includes('la campagne C2,'))) fautes.push('le modèle arrêté a été activé');
  }
  // 3. coupure juste APRÈS le « oui » de Robe Sara (son activation pas encore tentée) : au redémarrage, une par une
