    fs.writeFileSync(fauxWilayas, JSON.stringify({ brut: { ad_entities: [{ id: 'S9', targeting: JSON.stringify({ geo_locations: { regions } }) }] }, structure: { regions: [...regions.map(({ key, name }) => ({ key, name })), { key: '2499', name: 'Annaba' }] } }));
    const r = await api('/api/reglages/wilayas', {});
    const cleDe = (lst, w) => (lst.find(x => x.wilaya === w) || {}).key;
    if (r.statut !== 200 || r.corps.regions.length !== 25 || cleDe(r.corps.regions, 'Alger') !== '2401' || cleDe(r.corps.regions, 'Blida') !== '2404' || cleDe(r.corps.regions, 'Annaba') !== '928' || r.corps.confirme !== false || !r.corps.ecartes.some(e => e.key === '2499')) throw new Error('lecture des wilayas : ' + r.statut + ' ' + JSON.stringify(r.corps).slice(0, 300));
    const tourW = fs.readFileSync(journalClaude, 'utf8').split('\n').filter(Boolean).map(l => JSON.parse(l)).filter(x => x.etape === 'wilayas').pop();
    if (!tourW || !tourW.outils.some(o => o.endsWith('__ads_get_ad_entities')) || tourW.outils.some(o => /create|update|activate|delete/.test(o))) throw new Error('outils du tour des wilayas : ' + JSON.stringify(tourW));
    let fichier = JSON.parse(fs.readFileSync(configLocal, 'utf8'));
    if (fichier.ciblage?.type !== 'regions' || fichier.ciblage.confirme !== false || fichier.ciblage.regions.length !== 25 || fichier.ciblage.regions.some(x => x.key === '2499')) throw new Error('config.local.json : ' + JSON.stringify(fichier.ciblage).slice(0, 300));
    l = await ligneW(); if (!l || l.verdict !== 'ECHEC' || !/à confirmer/.test(l.detail)) throw new Error('liste à cocher avant confirmation : ' + JSON.stringify(l));
    const toutes = r.corps.regions.map(x => x.key);
    const c = await api('/api/reglages', { ciblage: { vus: toutes, garder: toutes.filter(k => k !== '2404'), confirme: true } });
    fichier = JSON.parse(fs.readFileSync(configLocal, 'utf8'));
    if (c.statut !== 200 || fichier.ciblage.confirme !== true || fichier.ciblage.regions.length !== 24 || fichier.ciblage.regions.some(x => x.key === '2404') || c.corps.ciblage.confirme !== true) throw new Error('confirmation : ' + JSON.stringify(fichier.ciblage).slice(0, 300));
    l = await ligneW(); if (l.verdict !== 'PASSE') throw new Error('liste à cocher après confirmation : ' + JSON.stringify(l));
