    if (faux.statut !== 400 || apres.nom === 'Ne doit pas passer' || apres.ciblage.regions.length !== 24) throw new Error('une clé « DZ » ajoutée : ' + faux.statut + ' ' + JSON.stringify(apres.ciblage).slice(0, 200));
